"""Browser UI for measured local-model comparisons. No external frontend dependencies."""
PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Compare systems · AgentReroute</title>
<style>
:root{--paper:#f7f4ed;--card:#fffefa;--ink:#252b2a;--muted:#737970;--line:#dedfd5;--blue:#294b76;--green:#38634e;--gold:#ad8543;--red:#a04c45;--mono:ui-monospace,SFMono-Regular,Consolas,monospace}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px system-ui,-apple-system,sans-serif}button,select,input{font:inherit}button,a,select,input{outline-offset:4px}button{cursor:pointer}button:disabled{cursor:default;opacity:.45}a{color:inherit}.shell{max-width:1510px;margin:auto;padding:0 32px 36px}.nav{height:74px;display:flex;align-items:center;gap:30px;border-bottom:1px solid var(--line)}.brand{font-family:Georgia,serif;font-size:23px;margin-right:20px;text-decoration:none}.brand b{color:var(--gold);font-size:26px;margin-right:8px}.nav-link{font-size:12px;text-decoration:none;padding:27px 0;color:var(--muted);border-bottom:2px solid transparent}.nav-link.active{color:var(--ink);border-bottom-color:var(--green)}.local{margin-left:auto;color:var(--green);font:10px var(--mono);letter-spacing:1px}.local:before{content:'●';margin-right:8px}.intro{padding:32px 0 24px;display:flex;align-items:center;justify-content:space-between;gap:24px}.eyebrow{color:var(--gold);font:10px var(--mono);letter-spacing:1.9px;text-transform:uppercase}.intro h1{font-family:Georgia,serif;font-weight:400;font-size:38px;letter-spacing:-1px;margin:9px 0 10px}.intro p{color:var(--muted);max-width:690px;line-height:1.7;font-size:13px;margin:0}.principles{display:flex;gap:24px;white-space:nowrap;font-size:11px;color:var(--muted)}.principles span{display:block;font:18px Georgia,serif;color:var(--ink);margin-bottom:6px}.controls{display:grid;grid-template-columns:minmax(240px,1fr) minmax(230px,1.3fr) auto;gap:14px;background:var(--card);padding:18px;border:1px solid var(--line);border-radius:10px}.field{min-width:0}.field label{display:block;font:10px var(--mono);text-transform:uppercase;letter-spacing:1px;color:var(--muted);margin-bottom:8px}.field select{width:100%;background:#f7f8f3;border:1px solid var(--line);border-radius:5px;color:var(--ink);padding:10px 30px 10px 10px;font-size:12px;text-overflow:ellipsis}.run-actions{display:flex;align-items:flex-end;gap:7px}.button{border:1px solid var(--line);background:var(--card);color:var(--ink);border-radius:5px;padding:10px 14px;font-size:12px}.button.primary{background:var(--green);color:white;border-color:var(--green)}.button.small{padding:7px 10px}.notice{font-size:11px;color:var(--muted);line-height:1.7;margin:12px 0 20px}.error{padding:12px 15px;border:1px solid #dfc3bf;background:#fcf0ee;color:#843d36;border-radius:6px;font-size:12px;white-space:pre-wrap;margin:12px 0}.error:empty{display:none}.runbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:20px 0 14px}.runbar h2{font:20px Georgia,serif;margin:0}.status-line{font:10px var(--mono);color:var(--muted)}.live-pill{color:var(--green)}.playback{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.playback input{width:150px;accent-color:var(--green)}#cursor-label{min-width:90px;color:var(--muted);font:10px var(--mono)}.columns{display:grid;grid-template-columns:1fr 1fr;gap:18px}.system{min-width:0;background:var(--card);border:1px solid var(--line);border-top:3px solid var(--blue);border-radius:9px;overflow:hidden}.system.reroute{border-top-color:var(--green)}.system-head{padding:20px 21px 15px;display:flex;align-items:flex-start;justify-content:space-between}.system h2{font:29px Georgia,serif;margin:0 0 6px;letter-spacing:-.5px}.system .kicker{font:9px var(--mono);letter-spacing:1px;color:var(--blue);text-transform:uppercase}.reroute .kicker{color:var(--green)}.badge{border:1px solid var(--line);border-radius:20px;padding:5px 9px;font:10px var(--mono);color:var(--muted);white-space:nowrap}.badge.running{color:var(--blue);background:#edf2f8;border-color:#c6d5e5}.badge.completed{color:var(--green);background:#edf4ee;border-color:#c6d9cc}.badge.error,.badge.partial{color:var(--red);background:#faefeb;border-color:#e6cbc2}.algorithm{padding:0 21px 18px;display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.stage{border:1px solid var(--line);background:#fafbf7;border-radius:5px;min-height:54px;padding:9px 8px;font-size:11px;color:var(--muted);position:relative}.stage i{display:block;font:9px var(--mono);font-style:normal;margin-bottom:4px;color:#9a9e96}.stage.active{border-color:#9eb4cd;background:#edf2f8;color:var(--blue);box-shadow:inset 2px 0 var(--blue)}.reroute .stage.active{border-color:#a7c2b1;background:#edf4ee;color:var(--green);box-shadow:inset 2px 0 var(--green)}.stage.done{color:var(--ink);background:#f2f5ed}.stage.failed{color:var(--red);border-color:#dfbdb5;background:#fbefec}.system-note{padding:0 21px 14px;color:var(--muted);font-size:10px;line-height:1.6;min-height:42px}.stats{display:grid;grid-template-columns:repeat(4,1fr);padding:14px 20px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:#fafaf5;gap:6px}.stat strong{display:block;font:23px Georgia,serif;font-weight:400}.stat span{font:9px var(--mono);color:var(--muted);display:block;margin-top:5px}.section{padding:16px 21px;border-bottom:1px solid var(--line)}.section:last-child{border-bottom:0}.section-title{font:10px var(--mono);text-transform:uppercase;letter-spacing:1px;color:var(--muted);margin:0 0 12px}.candidates{display:grid;gap:7px}.candidate{border:1px solid var(--line);border-radius:5px;padding:11px;display:grid;grid-template-columns:25px 1fr auto;gap:6px}.rank{font:18px Georgia,serif;color:var(--gold)}.candidate b{font-size:12px;font-weight:500}.candidate small{display:block;color:var(--muted);font-size:10px;margin-top:5px;word-break:break-word}.score{font:11px var(--mono);color:var(--green);text-align:right}.empty{font-size:12px;color:#92988f;line-height:1.7;margin:0;min-height:48px}.checks-line{display:flex;flex-wrap:wrap;gap:12px;color:var(--muted);font:10px var(--mono);line-height:1.8}.violation{color:var(--red)}.log{max-height:175px;overflow:auto;display:grid;gap:6px}.log-row{text-align:left;border:0;background:#f5f6f0;border-radius:4px;padding:8px;font:10px var(--mono);color:var(--muted);width:100%;word-break:break-word}.log-row b{color:var(--ink);font-weight:400}.log-row.failed{background:#fbefec;color:var(--red)}.outcome{font-size:12px;line-height:1.8;color:var(--muted)}.outcome strong{color:var(--ink);font-weight:500}.outcome .good{color:var(--green)}.outcome .bad{color:var(--red)}.input-run,.details-panel,.performance{background:var(--card);border:1px solid var(--line);border-radius:8px;margin-top:18px;padding:17px 20px}.input-run summary,.details-panel summary{cursor:pointer;font:15px Georgia,serif}.source-meta{color:var(--muted);font:10px var(--mono);line-height:1.8;margin:12px 0}.trace{display:flex;gap:7px;overflow:auto;padding-bottom:9px;margin-top:13px}.trace-step{flex:0 0 118px;border:1px solid var(--line);padding:9px;border-radius:5px;background:#f8f9f3;cursor:pointer;min-height:66px}.trace-step b{display:block;font:10px var(--mono);color:var(--blue);margin-bottom:7px}.trace-step span{font-size:10px;color:var(--muted)}.trace-step.focus{border-color:var(--green);background:#edf4ee}pre{white-space:pre-wrap;word-break:break-word;font:11px/1.7 var(--mono);color:var(--muted);max-height:300px;overflow:auto}.performance h3{font:19px Georgia,serif;margin:0 0 16px}.performance table{border-collapse:collapse;width:100%;font-size:12px}.performance td,.performance th{text-align:left;border-bottom:1px solid #eceee5;padding:10px 8px}.performance th{font:10px var(--mono);color:var(--muted);font-weight:400}.performance td:not(:first-child){font-family:var(--mono);font-size:11px}.performance p{font-size:10px;color:var(--muted);line-height:1.8;margin-bottom:0}.footer{font-size:10px;color:var(--muted);line-height:1.8;margin-top:18px;overflow-wrap:anywhere}.loading{animation:pulse 1.5s infinite}@keyframes pulse{50%{opacity:.45}}@media(max-width:1050px){.principles{display:none}.controls{grid-template-columns:1fr 1fr}.run-actions{grid-column:span 2}.runbar{align-items:flex-start;flex-direction:column}.algorithm{padding-left:13px;padding-right:13px}.section{padding:15px 13px}.system-head{padding:18px 13px}}@media(max-width:720px){.shell{padding:0 14px 24px}.nav{gap:15px;height:64px}.brand{font-size:18px;margin-right:0}.nav-link{font-size:11px;padding:23px 0}.local{display:none}.intro{padding:24px 0 20px}.intro h1{font-size:31px}.controls{grid-template-columns:1fr}.run-actions{grid-column:auto}.columns{grid-template-columns:1fr}.playback input{width:120px}.system h2{font-size:26px}.performance{overflow:auto}}
</style></head><body><main id="comparison-app" class="shell">
<nav class="nav" aria-label="Main navigation"><a class="brand" href="/"><b>⚜</b>AgentReroute</a><a class="nav-link" href="/">Execution view</a><a class="nav-link active" href="/compare" aria-current="page">Compare systems</a><span class="local" id="connection">LOCAL OLLAMA</span></nav>
<header class="intro"><div><div class="eyebrow">Algorithm observatory / live comparison</div><h1>Two paths. One agent run.</h1><p>Follow AgentRx and AgentReroute as they inspect the same trace, locate a fault, and attempt a correction. Every model request is made to your local Ollama server.</p></div><div class="principles"><div><span>01</span>Identical input</div><div><span>02</span>Actual inference</div><div><span>03</span>Observed outcomes</div></div></header>
<form id="run-form" class="controls"><div class="field"><label for="scenario">Recorded scenario</label><select id="scenario" required><option value="">Loading scenarios…</option></select></div><div class="field"><label for="model">Installed Ollama model</label><select id="model" required><option value="">Connecting to Ollama…</option></select></div><div class="run-actions"><button id="start-run" class="button primary" type="submit" disabled>▶ Run comparison</button><button id="cancel-run" class="button" type="button" disabled>Stop</button></div></form>
<p class="notice">Controlled input trace and scripted user · Real model inference for diagnosis and post-rollback agent turns · AgentReroute starts with initial weights, without a trained checkpoint.</p><div id="error" class="error" role="alert"></div>
<div class="runbar"><div><h2>Execution, side by side</h2><p class="status-line" id="run-status" aria-live="polite">Ready when you are. Both systems receive the same recorded input.</p></div><div class="playback" aria-label="Shared event playback"><button class="button small" id="previous" type="button" aria-label="Previous event">←</button><button class="button small" id="play" type="button">Pause playback</button><button class="button small" id="next" type="button" aria-label="Next event">→</button><input id="cursor" type="range" min="0" max="0" value="0" aria-label="Event timeline"><span id="cursor-label">0 / 0 events</span><button class="button small" id="go-live" type="button">Go live</button></div></div>
<div class="columns" id="systems"></div>
<details class="input-run" open><summary>Shared input · the same trace for both systems</summary><p class="source-meta" id="input-meta">The recorded multi-agent execution appears here when a comparison starts.</p><div class="trace" id="trace"></div><pre id="trace-detail">Select a step to inspect its messages and tool calls.</pre></details>
<section class="performance"><h3>Observed performance</h3><table><thead><tr><th>THIS EXECUTION</th><th>AGENTRX</th><th>AGENTREROUTE</th></tr></thead><tbody id="metrics"></tbody></table><p>Single-run measurements, not benchmark accuracy. Systems run sequentially to avoid competing for the GPU; elapsed time includes local model loading and queueing. Policy scores are action-selection weights, not calibrated failure probabilities. “Task met” is checked against the actual retail state and required outputs after the repair policy returns.</p></section>
<details class="details-panel"><summary>Event inspector · request responses and verification details</summary><pre id="event-detail">Start a comparison to inspect its events.</pre></details><footer class="footer" id="artifacts">No external API key required. Request, diagnosis and recovery artifacts are saved locally for each run.</footer>
</main><script>
'use strict';
const $=id=>document.getElementById(id), SIDES=['agentrx','agentreroute'];
const LABELS={agentrx:['AgentRx','Global constraints','Dynamic constraints','Guarded checks','Single judge','Shared repair','Verify outcome'],agentreroute:['AgentReroute','P1 · Intent & plan','P2 · Tool execution','P3 · Handoff & facts','Policy ranking','Shared repair','Verify + update']};
const S={events:[],cursor:0,following:true,playing:true,job:null,status:'idle',results:{},timer:null,loaded:false,trace:null,selectedStep:null};
function text(tag,value,cls){const el=document.createElement(tag);el.textContent=value??'';if(cls)el.className=cls;return el;}
function fmt(v,unit=''){return typeof v==='number'?v.toLocaleString(undefined,{maximumFractionDigits:2})+unit:'—';}
function showError(message){$('error').textContent=message||'';}
function stageFor(side,e){if(e.kind.startsWith('repair_')||(e.stage||'').startsWith('replay_agent'))return 4;if(e.kind==='verification_completed')return 5;if(e.kind==='attribution_completed')return 3;if(e.kind==='checks_completed')return side==='agentrx'?2:null;const stage=e.stage||'';if(side==='agentrx')return {global:0,dynamic:1,semantic:2,judge:3}[stage]??null;if(e.perspective)return {P1_INTENT_PLAN:0,P2_TOOL_EXECUTION:1,P3_HANDOFF_GROUNDING:2}[e.perspective]??null;return null;}
for(const side of SIDES){const card=text('section','',`system ${side==='agentreroute'?'reroute':''}`);card.id=side;card.setAttribute('aria-label',LABELS[side][0]+' execution');card.innerHTML=`<div class="system-head"><div><h2>${LABELS[side][0]}</h2><span class="kicker">${side==='agentrx'?'Constraint synthesis → one final judge':'Three perspectives → policy ranking'}</span></div><span class="badge" id="${side}-status">Ready</span></div><div class="algorithm" id="${side}-stages"></div><div class="system-note">${side==='agentrx'?'Full-evidence AgentRx · one-shot dynamic constraints · original joint judge.':'LLM constraints + deterministic seed checks · initial policy weights.'}</div><div class="stats"><div class="stat"><strong id="${side}-calls">—</strong><span>MODEL CALLS</span></div><div class="stat"><strong id="${side}-tokens">—</strong><span>OUTPUT TOKENS</span></div><div class="stat"><strong id="${side}-time">—</strong><span>MODEL TIME</span></div><div class="stat"><strong id="${side}-violations">—</strong><span>VIOLATIONS</span></div></div><div class="section"><h3 class="section-title">Fault attribution</h3><div class="candidates" id="${side}-candidates"></div></div><div class="section"><h3 class="section-title">Checks & evidence</h3><div class="checks-line" id="${side}-checks">No checks completed yet.</div></div><div class="section"><h3 class="section-title">Local model requests</h3><div class="log" id="${side}-log"></div></div><div class="section"><h3 class="section-title">Correction & verification</h3><div class="outcome" id="${side}-outcome"></div></div>`;$('systems').append(card);LABELS[side].slice(1).forEach((name,i)=>{const el=text('div','','stage');el.id=side+'-stage-'+i;el.append(text('i',String(i+1).padStart(2,'0')),text('span',name));$(side+'-stages').append(el);});}
function fold(){const states=Object.fromEntries(SIDES.map(s=>[s,{status:'Ready',requests:[],metrics:{},checks:null,hypotheses:null,verification:null,stages:{},result:null}]));for(const e of S.events.slice(0,S.cursor)){const p=states[e.system];if(!p)continue;if(e.kind==='system_started')p.status='running';if(e.kind==='request_started'){p.requests.push({...e,state:'running'});p.metrics.model_calls=(p.metrics.model_calls||0)+1;}if(e.kind==='request_completed'||e.kind==='request_failed'){const row=p.requests.find(r=>r.request_id===e.request_id);if(row)Object.assign(row,e,{state:e.kind==='request_failed'?'failed':'completed'});}if(e.metrics)p.metrics={...e.metrics};const observedRequest=p.requests.find(r=>r.request_id===e.request_id);const stage=stageFor(e.system,{...e,perspective:e.perspective||observedRequest?.perspective});if(stage!==null){if(e.kind==='request_started'||e.kind==='repair_started')p.stages[stage]='active';else if(e.kind==='request_failed')p.stages[stage]='failed';else p.stages[stage]='done';}if(e.kind==='checks_completed'){p.checks=e.counts;p.seed_checks=e.seed_checks;p.checkRows=e.rows;}if(e.kind==='attribution_completed'){p.hypotheses=e.hypotheses;p.prediction=e.prediction;p.diagnosis_seconds=e.diagnosis_seconds;}if(e.kind==='repair_started')p.directive=e.directive;if(e.kind==='repair_replayed')p.replay=e;if(e.kind==='verification_completed')p.verification=e;if(e.kind==='system_finished'){p.status=e.result.status;p.result=e.result;p.metrics=e.result.metrics;if(e.result.error)p.error=e.result.error;}}
return states;}
function candidates(side,p){const box=$(side+'-candidates');box.replaceChildren();if(p.hypotheses===null){box.append(text('p','Waiting for attribution. No prediction has been made.','empty'));return;}if(!p.hypotheses.length){box.append(text('p','Attribution abstained or produced no repairable candidate.','empty'));return;}p.hypotheses.slice(0,3).forEach((c,i)=>{const row=text('div','','candidate'),body=text('div');body.append(text('b',`${c.agent} · step ${c.step_index}`),text('small',c.mode||c.category));const score=text('div',c.confidence==null?'Not reported':fmt(c.confidence),'score');score.append(text('small',side==='agentreroute'?'policy score':'confidence'));row.append(text('span',String(i+1).padStart(2,'0'),'rank'),body,score);box.append(row);});}
function renderTrace(){const input=S.events.find(e=>e.kind==='input_ready');if(!input){$('trace').replaceChildren();$('input-meta').textContent='The recorded multi-agent execution appears here when a comparison starts.';return;}S.trace=input.trace;$('input-meta').textContent=`${input.trace.steps.length} recorded steps · Input ${input.input_hash.slice(0,12)} · Identical input for both systems`;
const holder=$('trace');if(holder.dataset.hash===input.input_hash)return;holder.dataset.hash=input.input_hash;holder.replaceChildren();for(const step of input.trace.steps){const event=step.substeps[0]||{},b=text('button','','trace-step');b.type='button';b.append(text('b',`#${step.index} · ${event.role||'event'}`),text('span',event.name||(event.tool_calls||[])[0]?.name||String(event.content||'').slice(0,35)));b.onclick=()=>{holder.querySelectorAll('button').forEach(n=>n.classList.remove('focus'));b.classList.add('focus');$('trace-detail').textContent=JSON.stringify(step,null,2);};holder.append(b);}}
function render(){const panels=fold();for(const side of SIDES){const p=panels[side],badge=$(side+'-status');badge.textContent=p.status==='Ready'&&S.job?(['completed','error','canceled'].includes(S.status)&&S.cursor===S.events.length?'Not run':'Queued'):p.status.replace('_',' ');badge.className='badge '+p.status;for(let i=0;i<6;i++)$(side+'-stage-'+i).className='stage '+(p.stages[i]||'');$(side+'-calls').textContent=fmt(p.metrics.model_calls);$(side+'-tokens').textContent=fmt(p.metrics.completion_tokens);$(side+'-time').textContent=fmt(p.metrics.model_seconds,'s');$(side+'-violations').textContent=p.checks?fmt(p.checks.VIOL):'—';candidates(side,p);const checks=$(side+'-checks');checks.replaceChildren();if(p.checks){for(const key of ['SAT','VIOL','SKIP','ERROR'])checks.append(text('span',`${key} ${p.checks[key]}`,key==='VIOL'?'violation':''));checks.append(text('span',`${p.seed_checks||0} seed evaluations`));}else checks.textContent='No checks completed yet.';const log=$(side+'-log');log.replaceChildren();for(const request of p.requests.slice(-6)){const button=text('button','','log-row '+(request.state==='failed'?'failed':''));button.type='button';button.append(text('b',`${String(request.request_id).padStart(2,'0')}  ${request.stage}`),text('span',` · ${request.state}${request.seconds!=null?' · '+fmt(request.seconds,'s'):''}`));button.onclick=()=>{S.following=false;S.playing=false;S.cursor=S.events.findIndex(e=>e.seq===request.seq)+1;render();};log.append(button);}if(!p.requests.length)log.append(text('p','Requests will appear here as they are sent.','empty'));const out=$(side+'-outcome');out.replaceChildren();if(p.error)out.append(text('div',p.error,'bad'));else if(p.verification){const v=p.verification,goal=v.task_outcome.after.reward===1;out.append(text('strong',goal?'Task met':'Task not met',goal?'good':'bad'));out.append(text('div',`Decision: ${v.decision.status}. Repair acceptance: ${v.verification.accepted?'passed':'not accepted / no intervention'}.`));out.append(text('div',`Retail state: ${v.task_outcome.after.state_ok?'matched':'not matched'}. Required outputs: ${v.task_outcome.after.missing_outputs.length?'missing':'present'}.`));if(v.policy_update)out.append(text('div',`Observable feedback reward: ${fmt(v.policy_update.reward)}. Policy updated for this run.`));}else if(p.directive){out.append(text('strong',`Rollback to step ${p.directive.rollback_step}`),text('div',p.directive.text));}else out.append(text('p','Waiting for attribution and a repair decision.','empty'));}
const rows=[['Attribution elapsed',p=>fmt(p.diagnosis_seconds,'s')],['Total elapsed',p=>fmt(p.result?.metrics.elapsed_seconds,'s')],['Model requests',p=>fmt(p.metrics.model_calls)],['Input tokens',p=>fmt(p.metrics.prompt_tokens)],['Output tokens',p=>fmt(p.metrics.completion_tokens)],['Check violations',p=>p.checks?fmt(p.checks.VIOL):'—'],['Task met after intervention',p=>p.verification?(p.verification.task_outcome.after.reward===1?'Yes':'No'):'—']];$('metrics').replaceChildren();for(const [name,value] of rows){const tr=text('tr');tr.append(text('td',name),...SIDES.map(s=>text('td',value(panels[s]))));$('metrics').append(tr);}$('cursor').max=S.events.length;$('cursor').value=S.cursor;$('cursor-label').textContent=`${S.cursor} / ${S.events.length} events`;$('play').textContent=S.playing?'Pause playback':'Play events';$('previous').disabled=S.cursor===0;$('next').disabled=S.cursor===S.events.length;$('run-status').textContent=S.job?`${S.status}${S.following?' · following live events':' · historical playback'}${S.status==='running'?' · model calls can take several minutes':''}`:'Ready when you are. Both systems receive the same recorded input.';const e=S.events[S.cursor-1];$('event-detail').textContent=e?JSON.stringify(e,null,2):'No event selected.';renderTrace();}
async function api(path,options={}){const response=await fetch(path,options);let data;try{data=await response.json();}catch{throw Error('The local server returned an unreadable response.');}if(!response.ok)throw Error(data.error||`Request failed (${response.status})`);return data;}
function busy(value){$('start-run').disabled=value||!S.loaded||!!$('model').selectedOptions[0]?.disabled;$('cancel-run').disabled=!value;$('scenario').disabled=value;$('model').disabled=value;}
async function poll(){if(!S.job)return;try{const data=await api('/api/comparisons/'+S.job+'?after='+S.events.length);S.status=data.status;$('scenario').value=data.scenario;if(![...$('model').options].some(o=>o.value===data.model)){const recorded=text('option',data.model+' (recorded run)');recorded.value=data.model;recorded.disabled=true;$('model').append(recorded);}$('model').value=data.model;for(const e of data.events)if(!S.events.some(x=>x.seq===e.seq))S.events.push(e);if(S.following)S.cursor=S.events.length;$('artifacts').textContent='Artifacts: '+data.artifact_dir;busy(!['completed','error','canceled'].includes(data.status));if(data.cancel_requested&&data.status==='running')showError('Stop requested. The current Ollama call will finish; no further model requests will be sent.');if(data.cancel_requested&&data.status==='canceled')showError('Stopped. Completed requests remain available for inspection.');if(data.status==='error'){const error=S.events.findLast(e=>e.kind==='job_error');if(error)showError(error.error);}render();if(!['completed','error','canceled'].includes(data.status))S.timer=setTimeout(poll,900);}catch(error){showError(error.message);busy(false);}}
$('run-form').onsubmit=async e=>{e.preventDefault();if(!$('model').value)return;busy(true);showError('');try{const job=await api('/api/comparisons',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scenario:$('scenario').value,model:$('model').value})});clearTimeout(S.timer);S.job=job.id;S.events=[];S.cursor=0;S.following=true;S.playing=true;S.status='running';$('trace').dataset.hash='';$('trace-detail').textContent='Select a step to inspect its messages and tool calls.';sessionStorage.setItem('comparison-job',job.id);history.replaceState(null,'','/compare?run='+job.id);render();poll();}catch(error){showError(error.message);busy(false);}};
$('cancel-run').onclick=async()=>{try{await api('/api/comparisons/'+S.job+'/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});showError('Stop requested. Waiting for the current model call to finish.');}catch(error){showError(error.message);}};
function move(value){S.cursor=Math.max(0,Math.min(S.events.length,value));S.following=false;S.playing=false;render();}$('previous').onclick=()=>move(S.cursor-1);$('next').onclick=()=>move(S.cursor+1);$('cursor').oninput=e=>move(Number(e.target.value));$('go-live').onclick=()=>{S.following=true;S.playing=true;S.cursor=S.events.length;render();};$('play').onclick=()=>{S.playing=!S.playing;S.following=false;render();};setInterval(()=>{if(S.playing&&!S.following&&S.cursor<S.events.length){S.cursor++;render();}},800);
async function init(){render();try{const data=await api('/api/scenarios');$('scenario').replaceChildren();for(const row of data){const o=text('option',row.title);o.value=row.id;$('scenario').append(o);}}catch(error){showError(error.message);return;}
try{const models=await api('/api/models');$('model').replaceChildren();if(!models.models.length)throw Error('Ollama has no installed models. Install a model, then reload this page.');for(const name of models.models){const o=text('option',name);o.value=name;$('model').append(o);}S.loaded=true;busy(false);}catch(error){showError(error.message);$('connection').textContent='CONNECTION NEEDS ATTENTION';}
const saved=new URLSearchParams(location.search).get('run')||sessionStorage.getItem('comparison-job');if(saved){S.job=saved;await poll();}}
$('model').onchange=()=>{if(['idle','completed','error','canceled'].includes(S.status))busy(false);};init();
</script></body></html>'''
